WA=$(python3 -c "import json,os,sys
b=os.path.expanduser('~/Library/Application Support') if sys.platform=='darwin' else os.environ.get('APPDATA') or os.path.expanduser('~/.config')
c=[]
for d in (os.listdir(b) if os.path.isdir(b) else []):
 for k in ('ab2web.orca-wa-inbox','ab2web.wa-inbox'):
  p=os.path.join(b,d,'plugins',k); f=os.path.join(p,'current')
  if os.path.isfile(f):
   x=os.path.join(p,open(f).read().strip(),'bin')
   if os.path.isdir(x): c.append((os.path.getmtime(x),x))
 for prof in ('profiles/local-default/orca-data.json','orca-data.json'):
  g=os.path.join(b,d,prof)
  if os.path.isfile(g):
   try: s=json.load(open(g)).get('settings') or {}
   except Exception: continue
   for r in s.get('devPluginPaths') or []:
    x=os.path.join(r,'bin')
    if os.path.isdir(x): c.append((os.path.getmtime(x),x))
print(max(c)[1] if c else '')") && [ -x "$WA/wa-scope" ] || exit 1; "$WA/wa-scope" pending

